// quickjs-wasi's JSException shape: an Error subclass whose stack
// accessor pair the constructor exposes by deleting V8's own `stack`.
export class GuestError extends Error {
  handle;
  #stack;
  constructor(handle) {
    super("guest error " + handle);
    this.handle = handle;
    delete this.stack;
    this.#stack = "guest stack " + handle;
  }
  get stack() {
    return this.#stack;
  }
  set stack(v) {
    this.#stack = v;
  }
}
